[
  {
    "statement": "Evidence for the effectiveness of strategies to combat white-nose syndrome in bats is limited.",
    "citations": []
  },
  {
    "statement": "Only probiotic bacterium treatment has been studied experimentally to combat white-nose syndrome in bats.",
    "citations": []
  },
  {
    "statement": "Two randomized, controlled studies found that treating little brown bats with a probiotic bacterium increased survival in some contexts.",
    "citations": []
  },
  {
    "statement": "Treating little brown bats with a probiotic bacterium increased survival for bats within cages in a laboratory in Canada.",
    "citations": []
  },
  {
    "statement": "Treating little brown bats with a probiotic bacterium increased survival for free-flying bats in the USA.",
    "citations": []
  },
  {
    "statement": "Treating little brown bats with a probiotic bacterium had no significant effect on survival for caged bats in a mine.",
    "citations": []
  },
  {
    "statement": "Symptoms of white-nose syndrome were reduced when probiotic bacterium treatment occurred at the time of infection.",
    "citations": []
  },
  {
    "statement": "Symptoms of white-nose syndrome worsened when probiotic bacterium treatment was administered 21 days prior to infection.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effectiveness of breeding bats in captivity to supplement populations.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effectiveness of treating hibernacula environments to reduce pathogen reservoirs.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effectiveness of decontaminating clothing and equipment to prevent pathogen spread.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effectiveness of culling infected bats.",
    "citations": []
  },
  {
    "statement": "The effectiveness of several commonly proposed strategies to combat white-nose syndrome in bats remains unassessed.",
    "citations": []
  }
]

[
  {
    "statement": "To help bats cross roads and railways safely, various structures can be installed.",
    "citations": []
  },
  {
    "statement": "Structures that can be installed to help bats cross safely include bat gantries or bat bridges, overpasses, green bridges, underpasses or culverts, and hop-overs.",
    "citations": [
      "978",
      "977",
      "979",
      "976",
      "980"
    ]
  },
  {
    "statement": "Evidence shows that green bridges were used by 97% of bats crossing a road in one UK study.",
    "citations": [
      "979"
    ]
  },
  {
    "statement": "Bat gantries may be less effective at helping bats cross roads.",
    "citations": [
      "978"
    ]
  },
  {
    "statement": "Studies found that fewer bats used bat gantries than crossed the road below at traffic height.",
    "citations": [
      "978"
    ]
  },
  {
    "statement": "Some bat gantries were not used by bats at all.",
    "citations": [
      "978"
    ]
  },
  {
    "statement": "Overpasses showed mixed results, with some bat species using the overpasses.",
    "citations": [
      "977"
    ]
  },
  {
    "statement": "Despite the installation of overpasses, many bats still crossed the road below at traffic height or other locations.",
    "citations": [
      "977"
    ]
  },
  {
    "statement": "Underpasses and culverts were used by bats in varying proportions across multiple studies.",
    "citations": [
      "976"
    ]
  },
  {
    "statement": "Bat species adapted to cluttered habitats used smaller culverts more than bat species adapted to open habitats.",
    "citations": [
      "976"
    ]
  },
  {
    "statement": "There is currently no evidence available for hop-overs.",
    "citations": [
      "980"
    ]
  },
  {
    "statement": "No studies have evaluated the effectiveness of hop-overs.",
    "citations": [
      "980"
    ]
  }
]

[
  {
    "statement": "Evidence shows several effective operational adjustments can reduce bat fatalities at onshore wind farms.",
    "citations": []
  },
  {
    "statement": "Increasing the wind speed at which turbines become operational, known as 'cut-in speed', was the most extensively studied approach to reduce bat fatalities.",
    "citations": [
      "1960"
    ]
  },
  {
    "statement": "The majority of replicated studies in the USA and Canada found that increasing the 'cut-in speed' of turbines resulted in fewer bat fatalities.",
    "citations": [
      "1960"
    ]
  },
  {
    "statement": "Preventing turbine blades from turning at low wind speeds through 'feathering' proved effective in reducing bat fatalities.",
    "citations": [
      "970"
    ]
  },
  {
    "statement": "Five of six studies on 'feathering' showed that this practice reduced bat fatalities.",
    "citations": [
      "970"
    ]
  },
  {
    "statement": "Automatically reducing turbine blade rotation when bat activity is predicted to be high was effective in both German and US studies.",
    "citations": [
      "971"
    ]
  },
  {
    "statement": "Automatically reducing turbine rotation when bat activity is predicted to be high significantly reduced fatalities for all bat species combined and for individual species.",
    "citations": [
      "971"
    ]
  },
  {
    "statement": "A Canadian study found that slowing turbine blade rotation at low wind speeds reduced bat fatalities.",
    "citations": [
      "2939"
    ]
  },
  {
    "statement": "Ultrasonic deterrents have shown mixed results in reducing bat fatalities.",
    "citations": [
      "968"
    ]
  },
  {
    "statement": "Some studies found ultrasonic deterrents resulted in 21-51% fewer bat fatalities in the first year of use.",
    "citations": [
      "968"
    ]
  },
  {
    "statement": "The results of using ultrasonic deterrents were inconsistent in subsequent years and across different bat species.",
    "citations": [
      "968"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects of removing turbine lighting on bat fatalities.",
    "citations": [
      "969"
    ]
  }
]

[
  {
    "statement": "Evidence regarding the effectiveness of public education and engagement strategies for bat conservation is limited.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated educating the public to improve bat perception and behavior.",
    "citations": [
      "1000"
    ]
  },
  {
    "statement": "No studies were found that evaluated educating farmers, land managers and communities about bat benefits for habitat management.",
    "citations": [
      "2040"
    ]
  },
  {
    "statement": "One UK study on engaging farmers and landowners to manage land for bats showed promising results.",
    "citations": [
      "1936"
    ]
  },
  {
    "statement": "During a five-year project in the UK, the overall population of greater horseshoe bats at four maternity roosts increased.",
    "citations": [
      "1936"
    ]
  },
  {
    "statement": "During a five-year project in the UK, 77 bat-related management agreements covering approximately 6,536 ha of land were established.",
    "citations": [
      "1936"
    ]
  },
  {
    "statement": "A review of public awareness programs in the USA and Canada argued that education alone was not sufficient to change behavior.",
    "citations": [
      "162"
    ]
  },
  {
    "statement": "Education served as a necessary catalytic factor for economic incentives and law enforcement in public awareness programs.",
    "citations": [
      "162"
    ]
  },
  {
    "statement": "Education campaigns for other wildlife groups, such as reptiles, have shown measurable conservation benefits.",
    "citations": []
  },
  {
    "statement": "Education campaigns for other wildlife have led to increased abundance of Philippine crocodiles.",
    "citations": []
  },
  {
    "statement": "Education campaigns for other wildlife have led to reduced poaching of leatherback turtle nests.",
    "citations": []
  },
  {
    "statement": "Education campaigns for other wildlife have led to decreased human-caused mortality of Philippine crocodiles.",
    "citations": []
  },
  {
    "statement": "Similar evidence of measurable conservation benefits from education campaigns is lacking specifically for bat conservation initiatives.",
    "citations": []
  }
]

[
  {
    "statement": "Several alternative lighting strategies can minimize disturbance to bats.",
    "citations": []
  },
  {
    "statement": "Red lighting has shown promise as a strategy for minimizing disturbance to bats.",
    "citations": [
      "2021"
    ]
  },
  {
    "statement": "Studies found that red lighting resulted in higher activity for some bat species compared to white or green lighting.",
    "citations": [
      "2021"
    ]
  },
  {
    "statement": "More soprano pipistrelles emerged from roosts when the roosts were lit with red light compared to when the roosts were lit with white light.",
    "citations": [
      "2021"
    ]
  },
  {
    "statement": "Using ultraviolet filters on lights can be beneficial for minimizing disturbance to bats.",
    "citations": [
      "1020"
    ]
  },
  {
    "statement": "One study found that hedges lit with ultraviolet filtered lights had higher soprano pipistrelle activity than hedges lit with unfiltered light.",
    "citations": [
      "1020"
    ]
  },
  {
    "statement": "Low intensity lighting is a strategy to minimize disturbance to bats.",
    "citations": [
      "1994"
    ]
  },
  {
    "statement": "One controlled study in caves found that low intensity white lights or red lights resulted in fewer bat flights than full white lighting.",
    "citations": [
      "1994"
    ]
  },
  {
    "statement": "Directing lighting away from bat access points or habitats is a recommended strategy.",
    "citations": [
      "2019"
    ]
  },
  {
    "statement": "No studies have yet evaluated the effectiveness of directing lighting away from bat access points or habitats.",
    "citations": [
      "2019"
    ]
  },
  {
    "statement": "Using 'warm white' LED lights rather than 'cool' LED lights has been suggested as a potential strategy to minimize disturbance to bats.",
    "citations": [
      "2020"
    ]
  },
  {
    "statement": "No studies have evaluated the approach of using 'warm white' LED lights instead of 'cool' LED lights.",
    "citations": [
      "2020"
    ]
  }
]

[
  {
    "statement": "Several actions can be considered for protecting bats during and after mine closure and reclamation.",
    "citations": []
  },
  {
    "statement": "Modifying the microclimate of an abandoned mine by closing a man-made entrance resulted in a greater number of bats hibernating within the mine.",
    "citations": [
      "1964"
    ]
  },
  {
    "statement": "Restoring bat foraging habitat at ex-quarry sites can increase bat activity.",
    "citations": [
      "2286"
    ]
  },
  {
    "statement": "Gravel-sand pits had higher overall bat activity 10 years after restoration compared to before or during quarrying.",
    "citations": [
      "2286"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of retaining bat access points following mine closures.",
    "citations": [
      "1962"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of excluding bats from roosts prior to mine reclamation.",
    "citations": [
      "1961"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of retaining access points to caves.",
    "citations": [
      "1990"
    ]
  },
  {
    "statement": "The effectiveness of retaining bat access points following mine closures, excluding bats from roosts prior to mine reclamation, or retaining access points to caves remains unassessed in the scientific literature.",
    "citations": [
      "1962",
      "1961",
      "1990"
    ]
  }
]

[
  {
    "statement": "Legally protecting bat habitats is the most documented legislative action for bat conservation.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Five studies evaluating the legal protection of bat habitats found positive effects on bat populations.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Higher bat activity and abundance have been observed in protected areas compared to unprotected areas across Europe and India.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "One study found that the distributions of 10 of 11 bat species significantly overlapped with designated protection areas.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of legally protecting bat species.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effectiveness of enforcing existing habitat protection legislation.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effectiveness of controlling bat hunting through legislation.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effectiveness of regulating bat guano harvesting.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effectiveness of enforcing anti-trafficking regulations.",
    "citations": []
  }
]

[
  {
    "statement": "Evidence from action documents shows mixed results for bat roost conservation in transportation infrastructure.",
    "citations": []
  },
  {
    "statement": "A review study found that spaces created in bridges to replace those lost during bridge works were recolonized by bats in similar or greater numbers at four of eight sites.",
    "citations": [
      "1967"
    ]
  },
  {
    "statement": "A before-and-after study in Ireland found that a Daubenton's bat maternity colony continued roosting in similar numbers after crevices were retained during repairs.",
    "citations": [
      "1966"
    ]
  },
  {
    "statement": "One review found that Yuma myotis and Mexican free-tailed bats recolonised most maintained roosts in similar numbers.",
    "citations": [
      "1966"
    ]
  },
  {
    "statement": "One review found that pallid bats did not return after bridge replacement works.",
    "citations": [
      "1966"
    ]
  },
  {
    "statement": "Providing alternative roosts for bats, such as bat houses, during bridge replacement showed poor results.",
    "citations": [
      "2942"
    ]
  },
  {
    "statement": "At one site, bat houses provided during bridge replacement were used by fewer bats than the original roosts.",
    "citations": [
      "2942"
    ]
  },
  {
    "statement": "At three sites, bat houses provided during bridge replacement were not used at all.",
    "citations": [
      "2942"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects of excluding bats from roosts during maintenance.",
    "citations": [
      "2941"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects of changing the timing of maintenance work on bats.",
    "citations": [
      "2940"
    ]
  }
]

[
  {
    "statement": "The evidence for managing existing hedgerows for bats significantly outweighs the evidence for planting new hedgerows.",
    "citations": []
  },
  {
    "statement": "For existing hedgerow management, two UK studies evaluated managing hedges specifically for bats.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "Hedges trimmed three or more years prior had more bat species recorded compared to hedges trimmed during the previous winter.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "Hedges trimmed three or more years prior had higher activity of two bat species compared to hedges trimmed during the previous winter.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "One study found that up to one fifth of lesser horseshoe bats flew along an artificial hedgerow used to divert the bats to safe crossing points.",
    "citations": [
      "981"
    ]
  },
  {
    "statement": "For planting new hedgerows, one study found no evidence that planting new hedges has been evaluated for bats.",
    "citations": [
      "1942"
    ]
  },
  {
    "statement": "Another study found no studies evaluating the creation of new unlit bat commuting routes using planting.",
    "citations": [
      "2034"
    ]
  },
  {
    "statement": "No studies were found evaluating the management of hedgerows to benefit wildlife on farmland in general.",
    "citations": [
      "2382"
    ]
  },
  {
    "statement": "The evidence base is clearly weighted toward the management of existing hedgerows rather than the planting of new hedgerows.",
    "citations": []
  }
]

[
  {
    "statement": "Several actions can be taken to provide bat roosting sites in trees where natural cavities are lacking.",
    "citations": []
  },
  {
    "statement": "A replicated study in Australia found that eight of sixteen artificial hollows cut into trees were used by roosting long-eared bats.",
    "citations": [
      "2047"
    ]
  },
  {
    "statement": "The artificial hollows in the Australian study were created with two different entrance designs.",
    "citations": [
      "2047"
    ]
  },
  {
    "statement": "Forty-four studies found that bats used bat boxes installed in various habitats.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Bat boxes were found to be used by bats in habitats including forest, woodland, farmland, pasture, wetlands, and urban areas.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "A review of 109 studies found that 72 bat species used bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "The review found that 18 bat species commonly used bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "The review also found that 31 bat species used bat boxes as maternity roosts.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "The design of a bat box is an important factor for its use by bats.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Studies found that bats preferred black boxes over grey, white, or wooden boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Bat box occupancy varied with the box's orientation, height, and position, such as on buildings versus trees.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "A before-and-after study in the UK found that a roost reinstated by attaching a felled tree trunk to a nearby tree continued to be used by common noctule bats as a maternity roost.",
    "citations": [
      "2048"
    ]
  },
  {
    "statement": "Eleven studies evaluated the practice of creating alternative bat roosts within developments.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Some studies found that bats used purpose-built roosts after the original roosts were destroyed.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Other studies found that purpose-built roosts had lower usage by bats than the original roosts.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "No evidence was captured for the effects of providing bat boxes, bat grilles, and improvements to roosts.",
    "citations": [
      "95"
    ]
  },
  {
    "statement": "More research is needed on the effects of providing bat boxes, bat grilles, and improvements to roosts.",
    "citations": [
      "95"
    ]
  }
]

[
  {
    "statement": "The evidence for legally protecting bat habitats shows more positive outcomes compared to legally protecting bats during development activities.",
    "citations": []
  },
  {
    "statement": "Five studies on habitat protection found that legally protected sites had greater bat species richness compared to unprotected sites.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Five studies on habitat protection found that legally protected sites had higher bat activity and abundance compared to unprotected sites.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "One study found that the distributions of 10 out of 11 bat species overlapped with protected areas significantly more than by chance.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Legal protection for bats during development activities showed mixed results.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Four UK studies found that while development licences for bats increased, 81% of licensees did not conduct the required post-development monitoring.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Licensed activities during building developments had negative impacts on bats.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "68% of bat roosts were destroyed during licensed building developments.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Only 31-67% of compensation roosts provided for bats under licence were used by bats.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "New alternative roosts for bats were four times less likely to be used than retained roosts.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Retaining existing bat roosts and access points during development showed better outcomes.",
    "citations": [
      "947"
    ]
  },
  {
    "statement": "Two-thirds of retained bat roosts were used after development.",
    "citations": [
      "947"
    ]
  },
  {
    "statement": "Retained bat roosts were more likely to be used than newly created roosts.",
    "citations": [
      "947"
    ]
  }
]

[
  {
    "statement": "Twelve studies evaluated the effects of using organic farming instead of conventional farming on bat populations.",
    "citations": []
  },
  {
    "statement": "Eight of the twelve studies on organic farming and bats were conducted in Europe.",
    "citations": []
  },
  {
    "statement": "Two of the twelve studies on organic farming and bats were conducted in the USA.",
    "citations": []
  },
  {
    "statement": "One of the twelve studies on organic farming and bats was conducted in Canada.",
    "citations": []
  },
  {
    "statement": "One of the twelve studies on organic farming and bats was conducted in Chile.",
    "citations": []
  },
  {
    "statement": "The community response of bats to organic versus conventional farming was mixed.",
    "citations": []
  },
  {
    "statement": "One study found no difference in bat species composition between organic and non-organic farms.",
    "citations": []
  },
  {
    "statement": "Five of seven studies found no difference in species richness or diversity between organic and non-organic farms.",
    "citations": []
  },
  {
    "statement": "Two studies found more bat species on organic farms compared to non-organic farms.",
    "citations": []
  },
  {
    "statement": "The population response of bats to organic versus conventional farming also varied.",
    "citations": []
  },
  {
    "statement": "Five of nine studies found no difference in overall bat activity or common pipistrelle activity between organic and conventional farms.",
    "citations": []
  },
  {
    "statement": "Four studies found higher overall bat activity on organic farms.",
    "citations": []
  },
  {
    "statement": "Four studies found higher bat feeding activity on organic farms.",
    "citations": []
  },
  {
    "statement": "Four studies found higher Brazilian free-tailed bat activity on organic farms.",
    "citations": []
  },
  {
    "statement": "Four studies found higher activity for four of seven bat species on organic farms.",
    "citations": []
  },
  {
    "statement": "Two UK studies found higher activity of Myotis species over water and rivers on organic farms.",
    "citations": []
  },
  {
    "statement": "One French study found higher activity for two of three bat species over organic fields compared to conventionally managed fields.",
    "citations": []
  }
]

[
  {
    "statement": "Studies have examined several alternatives to bat exclusion during building developments.",
    "citations": []
  },
  {
    "statement": "Creating alternative bat roosts within developments has been tested.",
    "citations": []
  },
  {
    "statement": "The creation of alternative bat roosts has shown mixed results.",
    "citations": []
  },
  {
    "statement": "Some studies found that bats used purpose-built roosts in higher or similar numbers after original roosts were destroyed.",
    "citations": []
  },
  {
    "statement": "Other studies found lower usage by bats of purpose-built roosts after original roosts were destroyed.",
    "citations": []
  },
  {
    "statement": "Retaining existing bat roosts and access points during developments has been examined.",
    "citations": []
  },
  {
    "statement": "Retaining existing bat roosts and access points during developments showed more consistent success.",
    "citations": []
  },
  {
    "statement": "Retained roosts were used by similar or greater numbers of bats after development.",
    "citations": []
  },
  {
    "statement": "Retained roosts were more likely to be used by bats than newly created roosts.",
    "citations": []
  },
  {
    "statement": "Relocating access points to bat roosts was tested and showed limited success.",
    "citations": []
  },
  {
    "statement": "Bats showed reduced usage of roosts after access points were relocated.",
    "citations": []
  },
  {
    "statement": "Providing bat boxes has been extensively studied.",
    "citations": []
  },
  {
    "statement": "The effectiveness of bat boxes for displaced bats is variable.",
    "citations": []
  },
  {
    "statement": "Many studies found that bats used bat boxes in various habitats, including urban areas and buildings.",
    "citations": []
  },
  {
    "statement": "Specific studies found that bats displaced from buildings did not use provided bat houses.",
    "citations": []
  },
  {
    "statement": "Specific studies found that bats displaced from buildings did not use provided heated bat boxes.",
    "citations": []
  }
]

[
  {
    "statement": "Several factors are associated with successful artificial bat roost use by bats.",
    "citations": []
  },
  {
    "statement": "Microclimate management is crucial for the success of artificial bat roosts.",
    "citations": [
      "2052"
    ]
  },
  {
    "statement": "Bat numbers increased after artificial roosts were modified to reduce internal temperatures.",
    "citations": [
      "2052"
    ]
  },
  {
    "statement": "Bat boxes showed variable occupancy rates across different studies.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Thirty-one bat species used bat boxes as maternity roosts.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Only 18 bat species commonly used bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Design factors significantly influence the success of artificial bat roosts.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Black bat boxes were used more than grey, white, or wooden alternatives.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Bats showed preferences for specific designs of artificial roosts, including multi-compartment boxes.",
    "citations": [
      "1024"
    ]
